function mostrarGoals(){$.ajax({url:"/lib/webservices/referral-goals-ws.php",data:"showGoals=1",type:"POST",async:false,success:function(output){$(".table-row").remove();$("#goals-div").append(output)}})}function actualizarLinea(id){$("#goal-0").attr("name","goal-"+id);$("#goal-0").attr("onkeyup","saveGoal(this, "+id+")");$("#goal-0").attr("id","goal-"+id);$("#newOffer-0").attr("href","referral-goals/?newOffer="+id);$("#goalSelect-0").attr("id","goalSelect-"+id)}function saveGoal(thisObj,idGoal){var nGoal=$(thisObj).val();var currentId=$(thisObj).attr("id");var previousValue=$("#"+currentId+"-h").attr("value");if(nGoal!=previousValue){if($.isNumeric(nGoal)){if(nGoal!==""&&nGoal!="0"){$.ajax({url:"/lib/webservices/referral-goals-ws.php",data:"saveGoal=1&n="+nGoal+"&id="+idGoal,type:"POST",async:false,success:function(output){var json=JSON.parse(output);if(json.exists=="1"){$(thisObj).css("background-color","#FF9491")}else{if(json.id!="0"){actualizarLinea(json.id)}$(thisObj).css("background-color","#FFFFFF");$("#newOffer-0").removeAttr("disabled");$("#"+currentId+"-h").val(nGoal)}showError(json.code)}})}}else{$(thisObj).css("background-color","#FF9491")}}}function saveGoalOffer(thisObj){var idOffer=$(thisObj).val();var idGoal=$(thisObj).attr("id");$.ajax({url:"/lib/webservices/referral-goals-ws.php",data:"saveGoalOffer=1&idGoal="+idGoal+"&idOffer="+idOffer,type:"POST",success:function(output){var json=JSON.parse(output);if(json.id!="0"){var id=output.replace(/\s/g,"");actualizarLinea(id)}mostrarGoals();showError(json.code)}})}function addBlankLine(){$.ajax({url:"/lib/webservices/referral-goals-ws.php",data:"addBlankLine=1",type:"POST",success:function(output){$(".plusSpan").hide();$("#goals-div").append(output);$("#newOffer-0").attr("disabled","disabled")}})}function removeGoal(goal){$.ajax({url:"/lib/webservices/referral-goals-ws.php",data:"delGoal="+goal,type:"POST",success:function(output){var json=JSON.parse(output);$("#line-"+goal).remove();showError(json.code)}})}function removeOfferByType(field,type){var my=field;if(my.attr("id")=="select-wifi"){$("#select-wifi-conditions,#select-wifi-redeem_type").prop("disabled",true)}$.ajax({url:"/lib/webservices/referral-goals-ws.php",data:"type="+type+"&action=removeOfferByType",type:"POST",success:function(output){var data=JSON.parse(output);if(data.msgError!==""){showError(data.msgError)}$("#select-"+type).val([0])}})}$("#select-prestay, #select-wifi, #select-wifi-conditions, #select-wifi-redeem_type").on("change",function(){var my=$(this);value=my[0].value;type=my.data("type");if(value==0){removeOfferByType(my,type);return}if(my.attr("id")=="select-wifi"){$("#select-wifi-conditions,#select-wifi-redeem_type").prop("disabled",false)}switch(type){case"wifi":case"prestay":action="updateOfferByType";break;case"condicion":case"tipo_oferta":action="updateWifiOfferOptions";break}$.ajax({url:"/lib/webservices/referral-goals-ws.php",data:"value="+value+"&type="+type+"&action="+action,type:"POST",success:function(output){var json=JSON.parse(output);showError(json.code)}})});$("#input-offer-wifi-days").keyup(function(){var my=$(this);value=my[0].value;type=my.data("type");action="updateWifiOfferOptions";$.ajax({url:"/lib/webservices/referral-goals-ws.php",data:"value="+value+"&type="+type+"&action="+action,type:"POST",success:function(output){var json=JSON.parse(output);showError(json.code)}})});$("#selectStay, #stay-login-form, #stay-username, #stay-password, #stay-secret, #stay-time, #stay-siteID").on("change",function(){variables={action:"stay",stay:$("#selectStay").val()||"Set url...",loginUrl:$("#stay-login-form").val(),username:$("#stay-username").val(),password:$("#stay-password").val(),secret:$("#stay-secret").val(),time:$("#stay-time").val(),siteID:$("#stay-siteID").val(),userLang:$("#userLang").val()};for(var key in variables){if(variables[key]==undefined||variables[key]==null)delete variables[key]}console.log(variables);$.ajax({url:"/lib/webservices/referral-goals-ws.php",data:variables,type:"POST",success:function(output){var json=JSON.parse(output);showError(json.code)}})});$("#select-poststay").on("change",function(){if(this.value=="0"){removeStay("poststay")}else{$.ajax({url:"/lib/webservices/referral-goals-ws.php",data:"poststay="+this.value+"&action=poststay",type:"POST",success:function(output){var json=JSON.parse(output);showError(json.code)}})}});